'use strict';
/* The unchanged src/*.js + browser shims as one script that defines window.FPCore (used by web/build.js and the tests). */
const fs = require('node:fs');
const path = require('node:path');
const ROOT = path.join(__dirname, '..');
function bundleCore() {
  const mods = fs.readdirSync(path.join(ROOT, 'src')).filter(f => f.endsWith('.js')).sort();
  let core = `/* FuelPro core for the browser — generated by web/build.js from src/ (do not edit; edit src/ and rebuild) */\n`;
  core += fs.readFileSync(path.join(__dirname, 'shims', 'node-shims.js'), 'utf8') + '\n';
  core += fs.readFileSync(path.join(__dirname, 'shims', 'sqlite-sqljs.js'), 'utf8') + '\n';
  core += `(function (G) {\n'use strict';\nconst N = G.FP_NODE_SHIMS, Buffer = N.Buffer, process = N.process;\nconst defs = {};\n`;
  for (const f of mods) {
    const src = fs.readFileSync(path.join(ROOT, 'src', f), 'utf8');
    core += `defs[${JSON.stringify(f.replace(/\.js$/, ''))}] = function (module, exports, require, __dirname, __filename) {\n${src}\n};\n`;
  }
  core += `
  const cache = {};
  function req(name) {
    const n = String(name).replace(/^node:/, '');
    if (n === 'sqlite') { if (!G.FP_SQLITE) throw new Error('sqlite engine not ready'); return G.FP_SQLITE; }
    if (N[n]) return N[n];
    if (n === 'zlib' || n === 'os' || n === 'child_process') return {};
    const local = n.replace(/^\\.\\//, '').replace(/\\.js$/, '');
    if (!defs[local]) throw new Error('module not bundled: ' + name);
    if (cache[local]) return cache[local].exports;
    const module = { exports: {} }; cache[local] = module;
    defs[local].call(module.exports, module, module.exports, req, '/app/src', '/app/src/' + local + '.js');
    return module.exports;
  }
  req.main = null;
  G.FPCore = {
    require: req,
    modules: ${JSON.stringify(mods.map(f => f.replace(/\.js$/, '')))},
    /* start the real server code against the in-page database; returns request(method, url, {headers, body}) */
    start() {
      const { createApp } = req('./server');
      const app = createApp({ dbPath: '/page/fuelpro.db', mailer: { send: async (m) => { console.info('[mail in page]', m && m.subject); } }, appUrl: G.location ? G.location.origin : 'http://page' });
      const handler = G.__FP_HTTP_HANDLER;
      function request(method, url, opt = {}) {
        return new Promise((resolve) => {
          const ls = {}; const reqObj = { method, url, headers: Object.assign({ host: 'page' }, opt.headers || {}), socket: { remoteAddress: 'page' },
            on(ev, fn) { (ls[ev] = ls[ev] || []).push(fn); return reqObj; }, destroy() {} };
          const res = { status: 0, headers: {}, writeHead(s, h) { res.status = s; Object.assign(res.headers, h || {}); }, end(d) { resolve({ status: res.status, headers: res.headers, body: d == null ? '' : String(d) }); }, setHeader() {} };
          Promise.resolve(handler(reqObj, res)).catch((e) => resolve({ status: 500, headers: {}, body: JSON.stringify({ error: { code: 'INTERNAL', message: String(e && e.message) } }) }));
          if (opt.body != null) (ls.data || []).forEach(fn => fn(Buffer.from(String(opt.body))));
          (ls.end || []).forEach(fn => fn());
        });
      }
      return { request, db: app.db, engine: G.__FP_DB };
    }
  };
  })(typeof globalThis !== 'undefined' ? globalThis : window);
  `;
  return core;
}
module.exports = { bundleCore };
